internal static class HttpResourceRuntime
{
 public static async ValueTask<T>ReadAsync<T>(Uri uri,IExpression<string>?credential,IVariableResolver variables,ResourceFormat format,TypeSymbol type,IHttpTransport http,IAuthenticatedHttpTransport authenticated,ISecretStore secrets,ISecretAccessPolicy secretPolicy,IResourceDecoderRegistry decoders,CancellationToken ct){HttpResourceResponse response;if(credential is null)response=await http.GetAsync(uri,ct).ConfigureAwait(false);else{string name=credential.Evaluate(variables);secretPolicy.EnsureSecretAccess(name);if(!secrets.TryGet(name,out SecretValue?secret)||secret is null)throw new KeyNotFoundException($"Secret '{name}' is not defined.");response=await authenticated.GetAsync(uri,secret,ct).ConfigureAwait(false);}ResourceFormat media=Format(response.MediaType);if(media!=ResourceFormat.Unknown&&media!=format&&!(format==ResourceFormat.Json&&response.MediaType?.EndsWith("+json",StringComparison.OrdinalIgnoreCase)==true))throw new InvalidDataException($"HTTP resource '{uri}' was compiled as {format} but responded with '{response.MediaType}'.");ResourceDescriptor d=new(new HttpResourceReference(uri),format,type,"response");object value=decoders.Decode(d,new ResourcePayload(response.Content,response.MediaType,response.Charset,uri));return value is T typed?typed:throw new InvalidOperationException($"Decoder returned {value.GetType().Name}; expected {typeof(T).Name}.");}
 private static ResourceFormat Format(string?m){if(string.IsNullOrWhiteSpace(m))return ResourceFormat.Unknown;string v=m.Split(';')[0].Trim().ToLowerInvariant();if(v=="application/json"||v.EndsWith("+json",StringComparison.Ordinal))return ResourceFormat.Json;if(v is "text/plain" or "text/markdown")return ResourceFormat.Text;if(v is "text/csv" or "application/csv")return ResourceFormat.Csv;if(v is "application/xml" or "text/xml"||v.EndsWith("+xml",StringComparison.Ordinal))return ResourceFormat.Xml;if(v.StartsWith("image/",StringComparison.Ordinal))return ResourceFormat.Image;if(v=="application/octet-stream")return ResourceFormat.Binary;return ResourceFormat.Unknown;}
}
