,IResourceDecoderRegistry d,LanguageSnapshot l):ICommandHandler<GetHttpBinaryCommand,BinaryValue>{public ValueTask<BinaryValue>HandleAsync(GetHttpBinaryCommand c,CancellationToken x=default)=>HttpResourceRuntime.ReadAsync<BinaryValue>(c.Source.Evaluate(v),c.Credential,v,ResourceFormat.Binary,l.Types.Get<BinaryValue>(),h,a,s,p,d,x);}public sealed class GetHttpImageCommandHandler(IVariableResolver v,IHttpTransport h,IAuthenticatedHttpTransport a,ISecretStore s,ISecretAccessPolicy p,IResourceDecoderRegistry d,LanguageSnapshot l):ICommandHandler<GetHttpImageCommand,ImageValue>{public ValueTask<ImageValue>HandleAsync(GetHttpImageCommand c,CancellationToken x=default)=>HttpResourceRuntime.ReadAsync<ImageValue>(c.Source.Evaluate(v),c.Credential,v,ResourceFormat.Image,l.Types.Get<ImageValue>(),h,a,s,p,d,x);}public sealed class GetEnvironmentCommandHandler(IVariableResolver v):ICommandHandler<GetEnvironmentCommand,string>{private readonly IEnvironmentReader e=new ProcessEnvironmentReader();public ValueTask<string>HandleAsync(GetEnvironmentCommand c,CancellationToken x=default){x.ThrowIfCancellationRequested();string n=c.Name.Evaluate(v);return ValueTask.FromResult(e.Get(n)??throw new KeyNotFoundException($"Environment variable '{n}' is not defined."));}}
